"""Local assets only; works inside HA ingress without scripts or web fonts."""
STYLE='''
:root{color-scheme:light;--ink:#172c40;--muted:#64758a;--line:#dce5ed;--accent:#087f78;--surface:#fff}
*{box-sizing:border-box}body{margin:0;background:#f3f6fa;color:var(--ink);font:16px/1.55 system-ui,sans-serif;overflow-wrap:anywhere}
a{color:#096b68;text-underline-offset:3px}a:focus-visible,button:focus-visible,input:focus-visible,select:focus-visible,textarea:focus-visible,summary:focus-visible{outline:3px solid #db9022;outline-offset:4px}
.app-header{min-height:130px;position:fixed;top:0;left:0;width:238px;padding:30px 24px 20px;background:#122c3e;color:#fff;z-index:2}
.brand{display:flex;align-items:center;gap:12px;color:#fff;text-decoration:none}.brand-mark{display:grid;place-items:center;width:38px;height:42px;border:1px solid #54c8b0;border-radius:12px;color:#71e1c7;font-weight:750}.brand strong{font-size:21px;letter-spacing:-.5px}.app-header small{display:block;font-size:12px;color:#b0c7d6;margin-top:12px}
.main-nav{position:fixed;top:130px;bottom:0;left:0;width:238px;padding:16px;background:#122c3e;display:flex;flex-direction:column;gap:8px}
.main-nav a{display:block;color:#c8d8e4;text-decoration:none;padding:12px 14px;border-radius:9px;font-size:14px;border:1px solid transparent}
.main-nav a:hover{background:#213e51;color:#fff}.main-nav a[aria-current=page]{background:#244e59;color:#d9fff3;border-color:#38776f}
main{max-width:1580px;margin-left:238px;padding:36px 38px 70px}.page-heading{display:flex;align-items:center;justify-content:space-between;gap:24px;margin-bottom:26px}
h1{font-size:clamp(25px,3vw,34px);line-height:1.2;letter-spacing:-1px;margin:5px 0 12px}h2{font-size:22px;line-height:1.3;letter-spacing:-.4px;margin:8px 0 16px}h3{font-size:18px;line-height:1.4;margin:13px 0 9px}p{margin:10px 0 16px}.muted{color:var(--muted);font-size:14px}.eyebrow{color:#62768b;font-size:11px;font-weight:750;letter-spacing:1.5px;margin:0 0 6px}
.connection{padding:8px 12px;border:1px solid var(--line);border-radius:30px;background:#fff;font-size:13px;white-space:nowrap}.connection:before{content:'';display:inline-block;width:7px;height:7px;border-radius:50%;background:#8994a4;margin-right:8px}.connection.connected:before{background:#147f67}
.health-strip{display:flex;justify-content:space-between;align-items:center;gap:20px;padding:19px 22px;background:#fffaf0;border:1px solid #ecddba;border-left:4px solid #c0903b;border-radius:12px;margin-bottom:24px}.health-strip p{font-size:13px;color:#6c665c;margin:5px 0 0}.health-strip a{font-size:13px;flex-shrink:0}
.metrics{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:16px;margin-bottom:32px}.metric{display:flex;flex-direction:column;text-decoration:none;padding:18px 20px;background:#fff;border:1px solid var(--line);border-radius:12px;color:var(--ink)}.metric span{font-size:13px;font-weight:600;color:var(--muted)}.metric strong{font-size:34px;font-weight:650;line-height:1.3;margin:7px 0}.metric small{font-size:12px;color:var(--muted)}.metric:hover{border-color:var(--accent)}
.overview-grid{display:grid;grid-template-columns:minmax(0,1.65fr) minmax(270px,1fr);gap:28px}.results-grid{display:grid;grid-template-columns:1fr 1fr;gap:28px;margin:32px 0}.overview-grid>*,.results-grid>*{min-width:0}.section-heading{display:flex;justify-content:space-between;align-items:center;gap:14px}.count{display:grid;place-items:center;min-width:28px;height:28px;padding:0 8px;border-radius:9px;background:#e3eaf0;color:#4f6276;font-size:13px}
article,form,details,.panel{background:#fff;border:1px solid var(--line);border-radius:12px;padding:20px;margin:16px 0}.case-card{margin:0 0 14px;padding:20px 22px;border-left:3px solid #c99638}.case-top{display:flex;align-items:center;justify-content:space-between;gap:12px}.case-kind{font-size:11px;text-transform:uppercase;letter-spacing:1px;color:#6a7e8e;font-weight:700}.case-card p{font-size:14px;color:#5d6d7f}.case-footer{display:flex;justify-content:space-between;align-items:center;gap:14px;flex-wrap:wrap;padding-top:14px;margin-top:18px;border-top:1px solid #edf1f5}.case-footer span{font-size:12px;color:#738397}.case-footer a{font-size:13px;font-weight:600;text-decoration:none}.case-footer a span{color:inherit}
.badge{display:inline-block;background:#e9f2f3;color:#376b70;padding:4px 9px;border-radius:6px;font-size:11px;font-weight:600}.empty-state{border:1px dashed #cbd6e2;border-radius:12px;color:#67788b;font-size:14px;padding:24px;line-height:1.7;background:#f8fafc}.assistant-panel{padding:24px;background:#edf4f6;border:1px solid #d1e1e5;border-radius:12px;margin-top:22px}.assistant-panel h2{font-size:19px;margin-top:15px}.assistant-panel p{font-size:14px}.assistant-panel a{font-size:14px;font-weight:600}
.report-panel{margin-top:34px}.report-panel>form{padding:24px}.form-grid{display:grid;grid-template-columns:1fr 1fr;gap:18px}label{display:block;margin:12px 0;font-size:14px;font-weight:500}input:not([type=checkbox]):not([type=hidden]),select,textarea{display:block;width:100%;border:1px solid #b4c4d2;border-radius:7px;padding:11px 12px;margin-top:6px;font:inherit;color:var(--ink);background:#fff}input[type=checkbox]{width:auto}textarea{min-height:100px;resize:vertical}button{font:inherit;font-size:14px;font-weight:600;background:#08786f;color:#fff;border:1px solid transparent;border-radius:8px;padding:11px 17px;margin:6px 8px 6px 0;cursor:pointer}button:hover{background:#075f59}button[name=decision][value=reject]{background:#914347}
pre{overflow:auto;max-height:420px;font-size:13px;background:#eef3f6;padding:12px;border-radius:7px;white-space:pre-wrap;overflow-wrap:anywhere}summary{cursor:pointer;font-weight:600;font-size:14px}.notice{border-left:4px solid #a97112;background:#fff5df;padding:14px;border-radius:8px}ul{padding-left:22px}table{width:100%;border-collapse:collapse}td,th{text-align:left;padding:10px;border-bottom:1px solid #ddd}
@media(min-width:1600px){main{margin-right:auto;margin-left:calc(238px + (100vw - 1600px)/2)}}
@media(max-width:1100px){.app-header,.main-nav{width:205px}main{margin-left:205px;padding:28px 24px}.overview-grid{grid-template-columns:1fr}.overview-grid aside{display:grid;grid-template-columns:1fr 1fr;gap:22px}.assistant-panel{margin-top:0}.page-heading{align-items:flex-start}.metrics{gap:10px}.metric{padding:15px}}
@media(max-width:760px){.app-header{min-height:0;position:static;width:auto;padding:20px}.app-header small{margin:5px 0 0 50px}.main-nav{position:static;width:auto;padding:10px 14px;display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:6px}.main-nav a{padding:10px;font-size:12px}.main-nav a:last-child{grid-column:1/-1}main{margin:0;padding:24px 16px 40px}.page-heading{display:block}.connection{display:inline-block;margin-top:6px}.health-strip{display:block;padding:16px}.health-strip a{display:inline-block;margin-top:12px}.metrics{grid-template-columns:repeat(2,minmax(0,1fr));gap:10px}.metric{padding:16px}.metric strong{font-size:30px}.overview-grid aside,.results-grid,.form-grid{display:block}.overview-grid{gap:22px}.overview-grid aside>section,.results-grid>section{margin-bottom:24px}.assistant-panel{margin-top:22px}.case-card{padding:18px}.case-top{align-items:flex-start}.case-top .badge{max-width:60%}article,form,details{padding:16px}.report-panel>form{padding:18px}button{width:100%;margin:8px 0}table{display:block;overflow:auto}.case-footer{display:block}.case-footer a{display:block;margin-top:12px}}
'''
